entries[29456] = { ["name"] = "Gabe der Astralen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Schwert\n79 - 147 Schaden Tempo 2.00\n(56.50 Schaden pro Sekunde)\n+12 Beweglichkeit\n+18 Ausdauer\nHaltbarkeit 90 / 90\nBenötigt Stufe 63\nBenötigt Das Konsortium\n- Wohlwollend\nAnlegen: Erhöht die Angriffskraft um 24." }
entries[29457] = { ["name"] = "Nethersplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Dolch\n41 - 99 Schaden Tempo 1.70\n(41.18 Schaden pro Sekunde)\n+15 Ausdauer\n+18 Intelligenz\nHaltbarkeit 65 / 65\nBenötigt Stufe 63\nBenötigt Das Konsortium\n- Wohlwollend\nAnlegen: Erhöht die kritische Trefferwertung um 6.\nAnlegen: Erhöht die Zaubermacht um 61." }
entries[29458] = { ["name"] = "Aegis des Verteidigers", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n5279 Rüstung\n137 Blocken\n+21 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 70\nAnlegen: Erhöht die Zaubermacht um 28.\nAnlegen: Stellt alle 5 Sek. 14 Mana wieder her." }
entries[29459] = { ["name"] = "Melderdaten des Astraleums", ["text"] = "Questgegenstand\n\"Ein kleiner Kristall, der rasch die Farben wechselt.\"" }
entries[29460] = { ["name"] = "Gefängnisschlüssel des Astraleums", ["text"] = "Benutzen: Öffnet Gefängnisse des Astraleums." }
entries[29461] = { ["name"] = "Manabombenfragment", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Fragment des Mantels einer verheerenden Waffe, die bei der Zerstörung von Kirin'Var eingesetzt wurde.\"" }
entries[29463] = { ["name"] = "Bernsteinbänder des Aggressors", ["text"] = "Wird beim Aufheben gebunden\nHandgelenke Platte\n608 Rüstung\n+22 Stärke\n+18 Beweglichkeit\n+25 Ausdauer\nHaltbarkeit 55 / 55\nBenötigt Stufe 70\nAnlegen: Erhöht die Verteidigungswertung um 15." }
entries[29464] = { ["name"] = "Schieferhautschiefer", ["text"] = "Questgegenstand\n\"Es schwitzt ein öliges Sekret aus... eine Art Teer. Ihr seid von oben bis unten beschmutzt.\"" }
