entries[29475] = { ["name"] = "Besänftigender Staub", ["text"] = "Questgegenstand\n\"Mit diesem Zeug ist Vorsicht geboten, Ihr könntet Euch am Ende noch selbst besänftigen!\"" }
entries[29476] = { ["name"] = "Purpurkristallsplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 61" }
